function rL(){
  if(PRIZE_MODE==="fcvm"){rLFcvm();return;}
  var h='<div class="exp-bar no-print">'; 
  h+='<button class="exp-btn primary" onclick="printLetterOnly()">&#128424; Stampa / PDF</button>';
  h+='<button class="exp-btn btn-green" onclick="saveAllPDFsFolder()" title="Salva PDF in cartella (Chrome/Edge)">&#128194; Salva in Cartella PC</button>';
  h+='<button class="exp-btn btn-blue" onclick="saveAllPDFsZip()">&#128230; Scarica ZIP</button>';
  h+='</div>';
  var searchPool=PRIZE_MODE==="seasonal"?E.filter(function(e){return isSMVSM(e);}):E;
  var placeholder=PRIZE_MODE==="seasonal"?"Cerca SM/VSM...":"Cerca dipendente...";
  h+='<input placeholder="'+placeholder+'" id="lq" style="width:100%;padding:10px 14px;border-radius:6px;border:1px solid #d5d0c8;font-size:13px;font-family:inherit;background:#fff;margin-bottom:6px" class="no-print">';
  if(PRIZE_MODE==="seasonal"){
    h+='<div style="font-size:10px;color:#8a8680;margin-bottom:10px;padding:6px 10px;background:#faf9f7;border-radius:6px;border:1px solid #e5e1db">'+
       '&#127942; Modalità <b>Seasonal Bonus</b> — lettere disponibili solo per SM/VSM ('+searchPool.length+' dipendenti)</div>';
  }
  h+='<div id="lr" class="no-print"></div><div id="lc"></div>';
  document.getElementById("p1").innerHTML=h;
  document.getElementById("lq").oninput=function(){
    var q=this.value.toLowerCase();if(q.length<2){document.getElementById("lr").innerHTML="";return}
    var pool=PRIZE_MODE==="seasonal"?E.filter(function(e){return isSMVSM(e);}):E;
    var ma=[];for(var i=0;i<pool.length&&ma.length<15;i++){var e=pool[i];if((e.c&&e.c.toLowerCase().indexOf(q)>=0)||(e.n&&e.n.toLowerCase().indexOf(q)>=0)||(e.m&&e.m.toLowerCase().indexOf(q)>=0))ma.push(e)}
    var r='<div class="sr">';ma.forEach(function(e){var uU=e.cu==="USD";r+='<div class="si" data-m="'+esc(e.m)+'"><b>'+(uU?esc(e.n).toUpperCase()+' '+esc(e.c).toUpperCase():esc(e.n)+' '+esc(e.c))+'</b> \u2014 '+esc(e.m)+' \u2014 '+(uU?esc(e.s).toUpperCase():esc(e.s))+'</div>'});
    r+="</div>";document.getElementById("lr").innerHTML=r;
    document.querySelectorAll(".si").forEach(function(si){si.onclick=function(){sL(si.getAttribute("data-m"));document.getElementById("lr").innerHTML=""}});}
}

function printLetterOnly(){
  var lc=document.getElementById("lc");
  if(!lc||!lc.innerHTML.trim()){alert("Seleziona prima un dipendente.");return;}
  // Usa il dipendente correntemente visualizzato
  var pool=getLetterPool();
  var html=null;
  // Cerca il dipendente selezionato confrontando l'HTML con quello generato
  for(var i=0;i<pool.length;i++){
    var h=getLetterHtmlForPrint(i);
    if(h){html=h;break;} // Fallback: primo disponibile — di solito è quello corretto
  }
  // Approccio migliore: ricostruisci l'HTML dalla lettera correntemente visualizzata
  var css=document.querySelector("style")?document.querySelector("style").textContent:"";
  var letterContent=lc.innerHTML;
  html="<!DOCTYPE html><html><head><meta charset=\"UTF-8\"><style>"+
    css+
    "*{-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important;color-adjust:exact!important}"+
    "html,body{margin:0;padding:0;background:#fff;font-family:'DM Sans',sans-serif;font-size:13px}"+
    "@page{size:A4;margin:10mm}"+
    ".no-print{display:none!important}"+
    "</style>"+
    "<link href=\"https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\">"+
    "</head><body>"+letterContent+"</body></html>";
  var w=window.open("","_blank","width=900,height=700");
  if(!w){alert("Popup bloccato. Consenti i popup per questo sito.");return;}
  w.document.write(html);
  w.document.close();
  w.onload=function(){w.focus();w.print();};}

// Save ALL PDFs: opens a new window with all letters, user prints to PDF
// Each page has the employee ID as filename hint
function saveAllPDFs(){
  var miss=canProduceLetter();
  if(miss.length>0){alert("Impossibile generare le lettere.\n\nDati mancanti:\n\u2022 "+miss.join("\n\u2022 ")+"\n\nCarica i dati dalla tab Fonti Dati.");return}
  var isSeasonal=PRIZE_MODE==="seasonal";
  var folderName=MODE==="preventivo"?"preventivo":"consuntivo";
  var myl=getMonthYearLabel();var psf=getPdfSubfolder();
  var css=document.querySelector("style").textContent;
  var mm=String(CFG_MONTH).padStart(2,"0");
  var pool=isSeasonal?E.filter(function(e){return isSMVSM(e);}):E;
  var total=pool.length,done=0;
  // Progress overlay with cancel
  window._pdfCancelled=false;
  var ov=document.createElement("div");
  ov.style.cssText="position:fixed;top:0;left:0;right:0;bottom:0;background:#1a1714;z-index:99999;display:flex;flex-direction:column;align-items:center;justify-content:center;font-family:'DM Sans',sans-serif";
  ov.innerHTML='<div style="background:#2c2925;border:1px solid #55504a;border-radius:14px;padding:36px 48px;text-align:center;min-width:360px;box-shadow:0 8px 40px rgba(0,0,0,.7)">'+
    '<div style="font-size:11px;font-weight:700;letter-spacing:3px;text-transform:uppercase;color:#c9a96e;margin-bottom:10px">Boggi Milano</div>'+
    '<div style="font-size:22px;font-weight:800;color:#ffffff;margin-bottom:6px">Preparazione lettere</div>'+
    '<div style="font-size:13px;color:#c8c3bb;margin-bottom:24px">Costruzione documento in corso...</div>'+
    '<div style="width:100%;height:6px;background:#3d3a36;border-radius:3px;overflow:hidden;margin-bottom:16px"><div id="pdfBar2" style="width:0%;height:100%;background:#c9a96e;border-radius:3px;transition:width .2s"></div></div>'+
    '<div id="pdfCount2" style="font-size:13px;color:#e0dbd4;font-weight:600;margin-bottom:24px">0 / '+total+'</div>'+
    '<button onclick="window._pdfCancelled=true" style="padding:9px 28px;border-radius:7px;border:1px solid #6b6560;background:transparent;color:#e0dbd4;font-size:12px;font-weight:600;cursor:pointer;font-family:\"DM Sans\",sans-serif" onmouseover="this.style.background=\'#3d3a36\'" onmouseout="this.style.background=\'transparent\'">\u2715 Annulla</button>'+
    '</div>';
  document.body.appendChild(ov);
  var html='<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Lettere '+folderName.toUpperCase()+' - '+myl+'</title>';
  html+='<link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&display=swap" rel="stylesheet">';
  html+='<style>'+css+'</style><style>*{-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important;color-adjust:exact!important}body{background:#fff;font-family:"DM Sans",sans-serif;font-size:13px;color:#4e4b48}@page{size:A4;margin:8mm}.pg-hdr{font-size:8px;color:#b0a99f;text-align:right;margin-bottom:4px}</style></head><body>';
  var pathInfo=CFG_PDF_PATH?(CFG_PDF_PATH.replace(/[\/\\]$/,"")+"/"+psf[folderName==="preventivo"?"prev":"cons"]+"/"):folderName+"/";
  html+='<div style="background:#fff3cd;padding:12px 20px;border-radius:6px;margin-bottom:20px;font-size:12px;color:#856404"><b>Cartella: '+esc(pathInfo)+'</b> \u2014 Per salvare: Ctrl+P \u2192 Destinazione: "Salva come PDF".<br>Per salvare i singoli PDF in cartella, usa l\'app desktop WPF.</div>';
  function buildNext(i){
    if(window._pdfCancelled){document.body.removeChild(ov);return}
    if(i>=total){
      document.getElementById("pdfBar2").style.width="100%";
      document.getElementById("pdfCount2").textContent="Apertura finestra stampa...";
      html+="</body></html>";
      setTimeout(function(){
        document.body.removeChild(ov);
        if(window._pdfCancelled)return;
        var w=window.open("","_blank");
        w.document.write(html);w.document.close();
        setTimeout(function(){w.focus();w.print()},600);
      },200);
      return;
    }
    var e=pool[i];
    var fileLabel=isSeasonal?(e.m+"_"+CFG_SEASON+String(CFG_YEAR).slice(-2)):(e.m+"_"+mm+"_"+CFG_YEAR);
    html+='<div class="pg-hdr">'+esc(fileLabel)+" | "+folderName+"</div>";
    html+=isSeasonal?buildSeasonalLetterAuto(e):(isUSA(e.si,e)?buildLetterUSA(e):buildLetter(e));
    if(i<total-1)html+='<div style="page-break-after:always"></div>';
    done++;
    document.getElementById("pdfBar2").style.width=Math.round(done/total*100)+"%";
    document.getElementById("pdfCount2").textContent=done+" / "+total+" dipendenti";
    setTimeout(function(){buildNext(i+1)},0);
  }
  buildNext(0);
}

// Save ALL PDFs as ZIP with real PDF files
// Strategy: render each letter in an off-screen container using html2canvas tile-by-tile,
// then assemble pages in jsPDF manually — bypassing the viewport-height limit of html2canvas.
function saveAllPDFsZip(){
  if(typeof JSZip==="undefined"){alert("Libreria JSZip non caricata.");return}
  if(typeof html2canvas==="undefined"||!(window.jspdf||window.jsPDF)){alert("Librerie html2canvas/jsPDF non caricate.");return}
  var miss=canProduceLetter();
  if(miss.length>0){alert("Impossibile generare le lettere.\n\nDati mancanti:\n\u2022 "+miss.join("\n\u2022 ")+"\n\nCarica i dati dalla tab Fonti Dati.");return}
  var isSeasonal=PRIZE_MODE==="seasonal";
  var folderName=MODE==="preventivo"?"preventivo":"consuntivo";
  var mm=String(CFG_MONTH).padStart(2,"0");
  var psf=getPdfSubfolder();
  var zip=new JSZip();
  var pool=isSeasonal?E.filter(function(e){return isSMVSM(e);}):E;
  var total=pool.length,done=0;

  // Progress overlay with cancel button
  window._zipCancelled=false;
  var ov=document.createElement("div");
  ov.style.cssText="position:fixed;top:0;left:0;right:0;bottom:0;background:#1a1714;z-index:99999;display:flex;flex-direction:column;align-items:center;justify-content:center;font-family:'DM Sans',sans-serif";
  ov.innerHTML='<div style="background:#2c2925;border:1px solid #55504a;border-radius:14px;padding:36px 48px;text-align:center;min-width:360px;box-shadow:0 8px 40px rgba(0,0,0,.7)">'+
    '<div style="font-size:11px;font-weight:700;letter-spacing:3px;text-transform:uppercase;color:#c9a96e;margin-bottom:10px">Boggi Milano</div>'+
    '<div style="font-size:22px;font-weight:800;color:#ffffff;margin-bottom:6px">Generazione ZIP</div>'+
    '<div style="font-size:13px;color:#c8c3bb;margin-bottom:24px">Rendering PDF in corso...</div>'+
    '<div style="width:100%;height:6px;background:#3d3a36;border-radius:3px;overflow:hidden;margin-bottom:16px"><div id="zipBar" style="width:0%;height:100%;background:#c9a96e;border-radius:3px;transition:width .2s"></div></div>'+
    '<div id="zipCount" style="font-size:13px;color:#e0dbd4;font-weight:600;margin-bottom:24px">0 / '+total+'</div>'+
    '<button onclick="window._zipCancelled=true" style="padding:9px 28px;border-radius:7px;border:1px solid #6b6560;background:transparent;color:#e0dbd4;font-size:12px;font-weight:600;cursor:pointer;font-family:\'DM Sans\',sans-serif" onmouseover="this.style.background=\'#3d3a36\'" onmouseout="this.style.background=\'transparent\'">\u2715 Annulla</button>'+
    '</div>';
  document.body.appendChild(ov);

  // Off-screen container — must be in DOM and have real width, but pushed off-left
  // We use a very large height so the browser lays out the full content
  var css=document.querySelector("style").textContent;
  var wrap=document.createElement("div");
  wrap.style.cssText="position:fixed;left:-900px;top:0;width:800px;overflow:visible;z-index:1;background:#fff";
  document.body.appendChild(wrap);

  // A4 at 96dpi: 794×1123px. Scale=2 → canvas is 1588×2246. PDF page in mm: 210×297.
  var PAGE_W_PX=794, SCALE=2;
  var PAGE_W_MM=210, PAGE_H_MM=297;
  var MARGIN_MM=8;
  // Content area in mm
  var CONT_W_MM=PAGE_W_MM-MARGIN_MM*2; // 194mm
  var CONT_H_MM=PAGE_H_MM-MARGIN_MM*2; // 281mm
  // px per mm at scale=2: (794/210)*2 = ~7.562 px/mm
  var PX_PER_MM=(PAGE_W_PX/PAGE_W_MM)*SCALE;
  var PAGE_H_PX_SCALED=Math.round(PAGE_H_MM*PX_PER_MM); // height of one A4 page in canvas px
  var MARGIN_PX_SCALED=Math.round(MARGIN_MM*PX_PER_MM);
  var CONT_H_PX_SCALED=PAGE_H_PX_SCALED-MARGIN_PX_SCALED*2;

  function genNext(i){
    if(window._zipCancelled){
      document.body.removeChild(wrap);
      document.body.removeChild(ov);
      return;
    }
    if(i>=total){
      document.getElementById("zipCount").textContent="Compressione ZIP...";
      zip.generateAsync({type:"blob"}).then(function(blob){
        document.body.removeChild(wrap);
        document.body.removeChild(ov);
        var a=document.createElement("a");a.href=URL.createObjectURL(blob);
        a.download="Lettere_"+folderName+"_"+psf.fileBase+".zip";
        document.body.appendChild(a);a.click();document.body.removeChild(a);URL.revokeObjectURL(a.href);
      });
      return;
    }
    var e=pool[i];
    var fileName=getEmpPdfFilename(e);

    // Render letter HTML into wrap div
    wrap.innerHTML='<style>'+css+'</style>'+
      '<style>*{-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important}'+
      'body,div{font-family:"DM Sans",sans-serif;font-size:13px;color:#4e4b48}'+
      '.lt{max-width:800px;width:800px;box-shadow:none;border:none}</style>'+
      (isSeasonal?buildSeasonalLetterAuto(e):(isUSA(e.si,e)?buildLetterUSA(e):buildLetter(e)));

    // Wait for fonts + layout
    document.fonts.ready.then(function(){
      setTimeout(function(){
        var target=wrap.querySelector(".lt")||wrap;
        var fullH=target.scrollHeight||target.offsetHeight||1200;

        html2canvas(target,{
          scale:SCALE,
          useCORS:true,
          logging:false,
          allowTaint:true,
          backgroundColor:"#ffffff",
          width:PAGE_W_PX,
          height:fullH,
          windowWidth:PAGE_W_PX,
          windowHeight:fullH,
          x:0,y:0,
          scrollX:-wrap.getBoundingClientRect().left,
          scrollY:-wrap.getBoundingClientRect().top
        }).then(function(canvas){
          // Get jsPDF from UMD bundle
          var jsPDFCtor=window.jspdf&&window.jspdf.jsPDF||window.jsPDF;
          var pdf=new jsPDFCtor("portrait","mm","a4");
          var totalCanvasH=canvas.height;
          var pageContentH=CONT_H_PX_SCALED; // canvas px per page content area
          var numPages=Math.ceil(totalCanvasH/pageContentH);

          for(var p=0;p<numPages;p++){
            if(p>0)pdf.addPage();
            var sliceY=p*pageContentH;
            var sliceH=Math.min(pageContentH, totalCanvasH-sliceY);
            // Draw slice to temp canvas
            var tmpC=document.createElement("canvas");
            tmpC.width=canvas.width;
            tmpC.height=sliceH;
            tmpC.getContext("2d").drawImage(canvas, 0,sliceY, canvas.width,sliceH, 0,0, canvas.width,sliceH);
            var imgData=tmpC.toDataURL("image/jpeg",0.95);
            var imgHmm=(sliceH/PX_PER_MM);
            pdf.addImage(imgData,"JPEG", MARGIN_MM,MARGIN_MM, CONT_W_MM, imgHmm);
          }

          var pdfBuf=pdf.output("arraybuffer");
          zip.file(fileName,pdfBuf);
          done++;
          document.getElementById("zipBar").style.width=Math.round(done/total*100)+"%";
          document.getElementById("zipCount").textContent=done+" / "+total;
          setTimeout(function(){genNext(i+1)},80);
        }).catch(function(err){
          console.error("Canvas error for "+e.m+":",err);
          done++;
          document.getElementById("zipBar").style.width=Math.round(done/total*100)+"%";
          document.getElementById("zipCount").textContent=done+" / "+total+" (errore: "+e.m+")";
          setTimeout(function(){genNext(i+1)},80);
        });
      },250);
    });
  }

  document.fonts.ready.then(function(){genNext(0)});
}

function secHd(n,t,p,hideB){return'<div class="lt-section"><div class="lt-sec-head"><div><span class="lt-sec-num">'+n+')</span><span class="lt-sec-title">'+esc(t)+"</span></div>"+(hideB?"":"<span class=\"lt-sec-badge\" style=\""+(p?"background:#d4edda;color:#1b5e29":"background:#f8d7da;color:#721c24")+"\">"+(p?"\u2713":"\u2717")+"</span>")+"</div><div class=\"lt-sec-body\">"}
function secPd(l,v,c,p){return'<div class="lt-row" style="border-top:1px solid #e5e1db;padding-top:6px;margin-top:4px"><span class="lt-row-label" style="font-weight:700">'+esc(l)+'</span><span class="lt-row-val" style="font-weight:800;color:'+(p?"#2d7a3a":"#b0a99f")+'"><span class="lt-row-cur">'+c+"</span>"+v.toLocaleString("it-IT")+"</span></div>"}
function ltRow(l,v){return'<div class="lt-row"><span class="lt-row-label">'+esc(l)+'</span><span class="lt-row-val">'+v+"</span></div>"}

// ── Brand logo helpers ─────────────────────────────────────────────────
// Logo Boggi: JPEG RGB 315x360 (convertito dal CMYK originale col suo profilo ICC, poi ridotto):
// prima 832 KB (1,1 MB in base64) in ogni lettera/PDF/email, ora ~11 KB. Mostrato a 48px di altezza.
var _BOGGI_LOGO_IMG='<img src="data:image/jpeg;base64," style="height:48px;width:auto;object-fit:contain" alt="Boggi Milano">';
var _BB_LOGO_IMG='<img src="data:image/png;base64," style="height:48px;width:auto;object-fit:contain" alt="Brian&amp;Barry Milano">';
var _DB_LOGO_IMG='<img src="data:image/png;base64," style="height:48px;width:auto;object-fit:contain" alt="Double B Brian&amp;Barry">';
function _getBrandKey(sid){var n=parseInt(sid)||0;if(n>=5000&&n<=5999)return "bb";if(n>=6000&&n<=6999)return "db";return "boggi";}
function getBrandLogoImg(sid){var k=_getBrandKey(sid);return k==="bb"?_BB_LOGO_IMG:k==="db"?_DB_LOGO_IMG:_BOGGI_LOGO_IMG;}
function getBrandLogoImgFcvm(emp){
  var sid='';
  if(typeof FC_MAP!=='undefined'){Object.keys(FC_MAP).some(function(k){var mp=FC_MAP[k];if([].concat(mp.fc||[]).concat(mp.vm||[]).indexOf(emp.m)>=0){sid=k;return true;}});}
  if(!sid&&emp.bdg_stores&&emp.bdg_stores.length>0)sid=emp.bdg_stores[0].sid;
  return getBrandLogoImg(sid);
}
